function dnai_radar_categories() {
	return array(
		'Producteurs & exportateurs',
		'Logistique & routes',
		'Demande',
		'Marché & prix',
		'Événements à surveiller',
	);
}

function dnai_radar_seed() {
	$seed = array(
		array( 'Producteurs & exportateurs', 'Arabie Saoudite' ), array( 'Producteurs & exportateurs', 'Émirats (ADNOC)' ),
		array( 'Producteurs & exportateurs', 'Qatar' ), array( 'Producteurs & exportateurs', 'Iran' ),
		array( 'Producteurs & exportateurs', 'Russie' ), array( 'Producteurs & exportateurs', 'Kazakhstan (Tengiz)' ),
		array( 'Producteurs & exportateurs', 'Canada' ), array( 'Producteurs & exportateurs', 'États-Unis' ),
		array( 'Producteurs & exportateurs', 'Chine' ),
		array( 'Logistique & routes', "Détroit d'Ormuz" ), array( 'Logistique & routes', 'Mer Rouge / Bab-el-Mandeb' ),
		array( 'Logistique & routes', 'Mer Noire' ), array( 'Logistique & routes', 'Port de Vancouver' ),
		array( 'Logistique & routes', 'Taux de fret maritime' ),
		array( 'Demande', 'Engrais phosphatés (acide sulfurique)' ), array( 'Demande', 'Lixiviation des métaux' ),
		array( 'Demande', 'Activité raffinage / gaz acide' ),
		array( 'Marché & prix', 'Prix pétrole / gaz' ), array( 'Marché & prix', 'World Bank Pink Sheet' ),
		array( 'Marché & prix', 'Soufre CFR Chine / FOB Moyen-Orient' ),
		array( 'Événements à surveiller', 'Sanctions Russie / Iran' ), array( 'Événements à surveiller', 'Restrictions export Chine' ),
		array( 'Événements à surveiller', 'Conflits au Moyen-Orient' ), array( 'Événements à surveiller', 'Ouragans Golfe du Mexique' ),
		array( 'Événements à surveiller', 'Arrêts de raffineries' ),
	);
	$items = array();
	foreach ( $seed as $i => $row ) {
		$items[] = array( 'id' => 's' . $i, 'cat' => $row[0], 'label' => $row[1] );
	}
	return $items;
}

function dnai_radar_get_watchlist() {
	$wl = get_option( 'dnai_radar_watchlist', null );
	if ( ! is_array( $wl ) ) {
		$wl = dnai_radar_seed();
		update_option( 'dnai_radar_watchlist', $wl );
	}
	return $wl;
}

function dnai_radar_save_watchlist( $items ) {
	update_option( 'dnai_radar_watchlist', array_values( $items ) );
}

function dnai_radar_watchlist_text() {
	$by_cat = array();
	foreach ( dnai_radar_get_watchlist() as $it ) {
		$by_cat[ $it['cat'] ][] = $it['label'];
	}
	$out = '';
	foreach ( dnai_radar_categories() as $c ) {
		if ( ! empty( $by_cat[ $c ] ) ) {
			$out .= "\n[" . $c . '] ' . implode( ', ', $by_cat[ $c ] );
		}
	}
	return trim( $out );
}

