/* -------------------------------------------------------------------------
 * 4. REST proxy — keeps the API key server-side, avoids CORS
 * ---------------------------------------------------------------------- */
function dnai_radar_rest_nonce_ok( $request ) {
	return (bool) wp_verify_nonce( $request->get_header( 'X-WP-Nonce' ), 'wp_rest' );
}

add_action( 'rest_api_init', function () {
	register_rest_route( 'dnai-radar/v1', '/signal', array(
		'methods'             => 'POST',
		'callback'            => 'dnai_radar_rest_signal',
		'permission_callback' => 'dnai_radar_rest_nonce_ok',
	) );
	register_rest_route( 'dnai-radar/v1', '/watchlist', array(
		array(
			'methods'             => 'GET',
			'callback'            => 'dnai_radar_rest_get_watchlist',
			'permission_callback' => '__return_true',
		),
		array(
			'methods'             => 'POST',
			'callback'            => 'dnai_radar_rest_update_watchlist',
			'permission_callback' => 'dnai_radar_rest_nonce_ok',
		),
	) );
} );

function dnai_radar_rest_get_watchlist( WP_REST_Request $request ) {
	return new WP_REST_Response( array(
		'items'      => dnai_radar_get_watchlist(),
		'categories' => dnai_radar_categories(),
	), 200 );
}

function dnai_radar_rest_update_watchlist( WP_REST_Request $request ) {
	$action = sanitize_text_field( (string) $request->get_param( 'action' ) );
	$wl     = dnai_radar_get_watchlist();

	if ( 'add' === $action ) {
		$cat   = sanitize_text_field( (string) $request->get_param( 'cat' ) );
		$label = mb_substr( sanitize_text_field( wp_strip_all_tags( (string) $request->get_param( 'label' ) ) ), 0, 80 );
		$cats  = dnai_radar_categories();
		if ( ! in_array( $cat, $cats, true ) ) {
			$cat = $cats[0];
		}
		if ( '' !== $label ) {
			$wl[] = array( 'id' => 'i' . time() . wp_rand( 100, 999 ), 'cat' => $cat, 'label' => $label );
		}
	} elseif ( 'remove' === $action ) {
		$id = sanitize_text_field( (string) $request->get_param( 'id' ) );
		$wl = array_filter( $wl, function ( $it ) use ( $id ) { return $it['id'] !== $id; } );
	} elseif ( 'reset' === $action ) {
		$wl = dnai_radar_seed();
	} else {
		return new WP_REST_Response( array( 'error' => 'unknown action' ), 400 );
	}

	dnai_radar_save_watchlist( $wl );
	return new WP_REST_Response( array( 'items' => array_values( $wl ) ), 200 );
}

function dnai_radar_rest_signal( WP_REST_Request $request ) {
	$base  = dnai_radar_opt( 'base_url' );
	$path  = dnai_radar_opt( 'api_path', '/api/chat/completions' );
	$key   = dnai_radar_opt( 'api_key' );
	$model = dnai_radar_opt( 'model', 'radar-soufre' );
	$web   = dnai_radar_opt( 'web_search', '1' ) === '1';
	if ( ! $base || ! $key ) {
		return new WP_REST_Response( array( 'error' => 'not_configured', 'message' => 'Radar not configured. Set base URL, API key and model in Settings → D²nAI Radar.' ), 503 );
	}

	// Source of truth: the shared server-side watchlist (so any update impacts the search).
	$watchlist = dnai_radar_watchlist_text();

	$today = date_i18n( 'l j F Y' );
	$user  = "Watchlist actuelle à surveiller en priorité :\n" . $watchlist .
		"\n\nNous sommes le " . $today . ". Génère le radar soufre de cette semaine en respectant exactement le format demandé.";

	// System prompt is optional: if the field is left empty, send no system
	// message and let the OpenWebUI model carry the role (Option B).
	$messages = array();
	$sys = trim( (string) dnai_radar_opt( 'system_prompt', '' ) );
	if ( '' !== $sys ) {
		$messages[] = array( 'role' => 'system', 'content' => $sys );
	}
	$messages[] = array( 'role' => 'user', 'content' => $user );

	$payload = array(
		'model'    => $model,
		'messages' => $messages,
		'stream'   => false,
	);
	if ( $web ) {
		$payload['features'] = array( 'web_search' => true );
	}

	$resp = wp_remote_post( rtrim( $base, '/' ) . $path, array(
		'timeout' => 90,
		'headers' => array(
			'Authorization' => 'Bearer ' . $key,
			'Content-Type'  => 'application/json',
		),
		'body'    => wp_json_encode( $payload ),
	) );

	if ( is_wp_error( $resp ) ) {
		return new WP_REST_Response( array( 'error' => 'AI Lab unreachable: ' . $resp->get_error_message() ), 502 );
	}
	$code = wp_remote_retrieve_response_code( $resp );
	$raw  = wp_remote_retrieve_body( $resp );
	$body = json_decode( $raw, true );

	$content = dnai_radar_extract_content( $body );

	if ( $code >= 400 || '' === $content ) {
		if ( isset( $body['error']['message'] ) ) {
			$msg = $body['error']['message'];
		} elseif ( isset( $body['error'] ) && is_string( $body['error'] ) ) {
			$msg = $body['error'];
		} elseif ( isset( $body['detail'] ) ) {
			$msg = is_string( $body['detail'] ) ? $body['detail'] : wp_json_encode( $body['detail'] );
		} else {
			// 200 but no text we recognise: surface a snippet so we can diagnose the shape.
			$msg = 'HTTP ' . $code . ' sans texte exploitable. Réponse brute : ' . mb_substr( trim( wp_strip_all_tags( (string) $raw ) ), 0, 400 );
		}
		return new WP_REST_Response( array( 'error' => $msg ), 502 );
	}

	return new WP_REST_Response( array( 'reply' => $content ), 200 );
}

/* Extract the assistant text from an OpenAI/Open WebUI response, tolerating
   string content, array (multimodal) content, completion-style "text", and
   reasoning models that only fill reasoning_content. */
function dnai_radar_extract_content( $body ) {
	if ( ! is_array( $body ) ) {
		return '';
	}
	$choice = isset( $body['choices'][0] ) ? $body['choices'][0] : null;

	$c = isset( $choice['message']['content'] ) ? $choice['message']['content'] : null;
	if ( is_array( $c ) ) {
		$parts = array();
		foreach ( $c as $p ) {
			if ( is_string( $p ) ) {
				$parts[] = $p;
			} elseif ( is_array( $p ) && isset( $p['text'] ) ) {
				$parts[] = $p['text'];
			}
		}
		$c = implode( "\n", $parts );
	}
	$c = is_string( $c ) ? trim( $c ) : '';

	if ( '' === $c && isset( $choice['text'] ) ) {
		$c = trim( (string) $choice['text'] );
	}
	if ( '' === $c && isset( $body['message']['content'] ) && is_string( $body['message']['content'] ) ) {
		$c = trim( $body['message']['content'] );
	}
	if ( '' === $c && isset( $choice['message']['reasoning_content'] ) && is_string( $choice['message']['reasoning_content'] ) ) {
		$c = trim( $choice['message']['reasoning_content'] );
	}
	return $c;
}

